$ErrorActionPreference='Stop'
Add-Type -AssemblyName UIAutomationClient
Add-Type @"
using System;using System.Runtime.InteropServices;public class S360OpenApprovalHistory2{[DllImport("user32.dll")]public static extern bool SetForegroundWindow(IntPtr hWnd);[DllImport("user32.dll")]public static extern bool SetCursorPos(int X,int Y);[DllImport("user32.dll")]public static extern void mouse_event(uint flags,uint dx,uint dy,uint data,UIntPtr extra);}
"@
function Get-Win{$root=[System.Windows.Automation.AutomationElement]::RootElement;$wins=$root.FindAll([System.Windows.Automation.TreeScope]::Children,[System.Windows.Automation.Condition]::TrueCondition);return $wins|Where-Object {$_.Current.Name -like '*Society360*Google Chrome'}|Select-Object -First 1}
function Scroll-Sidebar($n){[S360OpenApprovalHistory2]::SetCursorPos(150,640)|Out-Null;for($j=0;$j -lt $n;$j++){[S360OpenApprovalHistory2]::mouse_event(0x0800,0,0,[uint32]4294967176,[UIntPtr]::Zero);Start-Sleep -Milliseconds 100}}
function Click-Button($name){$script:w=Get-Win;$all=$w.FindAll([System.Windows.Automation.TreeScope]::Descendants,[System.Windows.Automation.Condition]::TrueCondition);$b=$all|Where-Object {$_.Current.ControlType -eq [System.Windows.Automation.ControlType]::Button -and $_.Current.Name -eq $name -and -not $_.Current.IsOffscreen}|Select-Object -First 1;if(!$b){return $false};$r=$b.Current.BoundingRectangle;[S360OpenApprovalHistory2]::SetCursorPos([int]($r.X+$r.Width/2),[int]($r.Y+$r.Height/2))|Out-Null;[S360OpenApprovalHistory2]::mouse_event(2,0,0,0,[UIntPtr]::Zero);[S360OpenApprovalHistory2]::mouse_event(4,0,0,0,[UIntPtr]::Zero);Start-Sleep -Milliseconds 450;return $true}
$ws=New-Object -ComObject WScript.Shell;$null=$ws.AppActivate('Society360');$ws.SendKeys('{F5}');Start-Sleep -Seconds 2;$w=Get-Win;if(!$w){throw 'Society360 Chrome window missing'};$null=[S360OpenApprovalHistory2]::SetForegroundWindow([IntPtr]$w.Current.NativeWindowHandle);Scroll-Sidebar 5
if(!(Click-Button 'Reports & Analytics')){throw 'Reports & Analytics group not visible'};Scroll-Sidebar 2
if(!(Click-Button 'Audit & Governance')){throw 'Audit & Governance group not visible after opening Reports & Analytics'};Scroll-Sidebar 3
$w=Get-Win;$all=$w.FindAll([System.Windows.Automation.TreeScope]::Descendants,[System.Windows.Automation.Condition]::TrueCondition);$leaf=$all|Where-Object {$_.Current.ControlType -eq [System.Windows.Automation.ControlType]::Button -and $_.Current.Name -eq 'Approval History' -and -not $_.Current.IsOffscreen}|Select-Object -First 1;if(!$leaf){Scroll-Sidebar 3;$w=Get-Win;$all=$w.FindAll([System.Windows.Automation.TreeScope]::Descendants,[System.Windows.Automation.Condition]::TrueCondition);$leaf=$all|Where-Object {$_.Current.ControlType -eq [System.Windows.Automation.ControlType]::Button -and $_.Current.Name -eq 'Approval History' -and -not $_.Current.IsOffscreen}|Select-Object -First 1};if(!$leaf){throw 'Approval History submenu not visible'};try{$leaf.GetCurrentPattern([System.Windows.Automation.InvokePattern]::Pattern).Invoke()}catch{$r=$leaf.Current.BoundingRectangle;[S360OpenApprovalHistory2]::SetCursorPos([int]($r.X+$r.Width/2),[int]($r.Y+$r.Height/2))|Out-Null;[S360OpenApprovalHistory2]::mouse_event(2,0,0,0,[UIntPtr]::Zero);[S360OpenApprovalHistory2]::mouse_event(4,0,0,0,[UIntPtr]::Zero)};Start-Sleep -Seconds 2
$w=Get-Win;$all=$w.FindAll([System.Windows.Automation.TreeScope]::Descendants,[System.Windows.Automation.Condition]::TrueCondition);$rows=@($all|Where-Object {$_.Current.ControlType -eq [System.Windows.Automation.ControlType]::DataItem -and $_.Current.Name -match '^\d{1,2}/\d{1,2}/\d{2},'});$empty=$all|Where-Object {$_.Current.Name -eq 'No approval history records found.' -and -not $_.Current.IsOffscreen}|Select-Object -First 1;$search=$all|Where-Object {$_.Current.ControlType -eq [System.Windows.Automation.ControlType]::Edit -and $_.Current.Name -eq 'Search approver / entity / decision'}|Select-Object -First 1;Write-Output 'APPROVAL_HISTORY_VISIBLE_UI=OPEN';Write-Output ('SEARCH_INPUT='+[bool]$search);Write-Output ('EMPTY_STATE='+[bool]$empty);Write-Output ('ROW_COUNT_VISIBLE='+$rows.Count)
